/**
 * 보건복지부 / 국립중앙의료원 공모신청 표준 서식에 맞춘 개조식 사업계획서 생성 도구
 */
import { diagnoseEssentialCareRegion } from './diagnosis.js';
export async function generateProjectNarrative(params) {
    const diag = await diagnoseEssentialCareRegion({ sgg: params.sgg });
    const today = new Date().toISOString().split('T')[0];
    const fullText = `[${diag.지자체} 필수의료 취약지 개선 공모사업 계획서]
작성일자: ${today}
대상지역: ${diag.지자체} (종합 취약도: ${diag.종합_취약도_등급} / 취약점수: ${diag.종합_취약도_점수})

□ 1. 추진 배경 및 필요성 (필수의료 인프라 분석)
  ○ (골든타임 도달 한계) ${diag.지자체}은 권역응급의료센터 60분 이내 미도달 인구 비율이 기준치를 대폭 초과하여 중증응급환자의 신속한 초기 대응 및 골든타임 확보가 심각하게 위협받고 있음.
  ○ (자체충족률 결핍) 관내 의료이용률(RI)이 법정 기준치(30%)를 현저히 밑돌고 있어, 대다수 중증 환자가 원주·춘천·서울 등 타 권역으로 유출되며 전원 중 사망 위험 상존.

□ 2. 법정 기준 충족 여부 및 취약 분야 진단
  ○ (법정 기준 판정) 보건복지부 필수의료 취약지 고시 기준에 의거, 3대 필수의료 영역 중 [${diag.취약분야_수}]에 해당하여 [${diag.정부_지원_우선순위}]으로 최종 판정됨.
  ○ 분야별 세부 판정 현황:
    - 응급의료: ${diag.법정_분야별_판정결과.응급의료.취약여부} (${diag.법정_분야별_판정결과.응급의료.지표})
    - 분만모자: ${diag.법정_분야별_판정결과.분만_모자의료.취약여부} (${diag.법정_분야별_판정결과.분만_모자의료.지표})
    - 소아중증: ${diag.법정_분야별_판정결과.소아_중증진료.취약여부} (${diag.법정_분야별_판정결과.소아_중증진료.지표})

□ 3. 모자·소아 필수의료 인프라 결핍 현황
  ○ (분만 인프라 공백) 관내 분만실 부재 또는 분만 접근성 결여로 임산부의 원정 출산이 일상화되어 모자보건 안전망이 취약함.
  ○ (심야 소아 진료 부재) 소아 병상 공급 비율이 법정 기준치(60%)에 미달하고 야간·휴일 소아진료기관이 전무하여, 야간 소아 경련·고열 환자 발생 시 응급실 뺑뺑이 위험에 노출.

□ 4. 종합 건의 및 국비 지원 당위성
  ○ 본 공모사업 선정을 통해 지역책임의료기관 중심의 24시간 응급·소아 진료 당직체계 구축, 거점병원 간 원격 협진 네트워크 조성, 전문의 인건비 및 시설 보강 국비 지원을 건의함.`;
    return {
        지자체: diag.지자체,
        사업계획서_제목: `[${diag.지자체}] 2026년도 필수의료 취약지 개선사업 제안서`,
        통합_개조식_서술문: fullText,
        주요_섹션: {
            추진배경: '골든타임 도달 한계 및 환자 역외 유출',
            법정기준진단: diag.법정_분야별_판정결과,
            사업추진목적: '지역완결적 필수의료 체계 구축 및 국비 지원 타당성 입증',
        },
    };
}
